mkdir -p /tmp/work && cat > /tmp/work/run.py <<'E'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None
def req(path,method="GET"):
    global tok
    for _ in range(200):
        try:
            if tok is None and path!="/token":
                tok=req("/token","POST")["token"]
            r=urllib.request.Request(B+path,method=method,data=b"" if method=="POST" else None)
            if path!="/token": r.add_header("Authorization","Bearer "+tok)
            with urllib.request.urlopen(r,timeout=20) as f: return json.load(f)
        except urllib.error.HTTPError as e:
            body=e.read().decode()[:200]
            if e.code==401: tok=None
            elif e.code==404: return None
            elif e.code==429:
                w=e.headers.get("Retry-After"); 
                try: w=float(w)
                except: w=2
                print("429",w,body); time.sleep(w+0.2)
            else: print(e.code,body,path); time.sleep(1)
        except Exception as e: print("err",e); time.sleep(1)
    raise SystemExit("fail "+path)
seen={};dups=0;p=1
while p:
    d=req(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in seen: dups+=1
        else: seen[o["id"]]=o
    p=int(d["next"].split("=")[-1]) if d["next"] else 0
print(len(seen),dups)
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={"north":0,"south":0,"east":0,"west":0};n=0
for o in seen.values():
    if o["status"]!="shipped":continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o); t=t.replace(tzinfo=timezone.utc)
    if not(lo<=t<hi):continue
    c=o["customer_id"]
    if c not in cust: cust[c]=req(f"/customers/{c}")
    if cust[c] is None: print("missing cust",o);continue
    v=(o["amount_cents"]*(100-cust[c]["discount_pct"])+50)//100
    reg[cust[c]["region"]]+=v;n+=1
r={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(r,open("/workspace/result.json","w"),indent=2);print(r)
E
